1. Working Principle:
- Allocate a single 1D array `arr[MAX]`.
- Stack 1 starts from the left boundary (`index 0`) and grows towards the right. Pointer `top1` is initialized to `-1`.
- Stack 2 starts from the right boundary (`index MAX - 1`) and grows towards the left. Pointer `top2` is initialized to `MAX`.
- Stack Full condition: `top1 + 1 == top2`. This guarantees that neither stack reports overflow as long as any free element remains in the array.

2. C Functions:
```c
#define MAX 100
int arr[MAX];
int top1 = -1, top2 = MAX;

// Push into Stack 1
void push1(int val) {
    if (top1 + 1 == top2) {
        printf("Stack Overflow! Array is full.\n");
        return;
    }
    top1++;
    arr[top1] = val;
}

// Push into Stack 2
void push2(int val) {
    if (top1 + 1 == top2) {
        printf("Stack Overflow! Array is full.\n");
        return;
    }
    top2--;
    arr[top2] = val;
}

// Pop from Stack 1
int pop1() {
    if (top1 == -1) {
        printf("Stack 1 Underflow!\n");
        return -1;
    }
    int val = arr[top1];
    top1--;
    return val;
}

// Pop from Stack 2
int pop2() {
    if (top2 == MAX) {
        printf("Stack 2 Underflow!\n");
        return -1;
    }
    int val = arr[top2];
    top2++;
    return val;
}
```

